/*
 * Builds the BDOI PrimeReact theme (src/theme/bdoi/primereact-bdoi.css) from the stock
 * lara-light-indigo theme: the indigo palette becomes the BDO Insure palette and the font
 * becomes Nunito. Everything else in the theme (sizes, states, components) is unchanged.
 *
 *   node scripts/build-bdoi-theme.js
 *
 * Run it again after upgrading primereact, then commit the generated file.
 */
const fs = require("fs");
const path = require("path");

const source = path.join(
  __dirname,
  "..",
  "node_modules",
  "primereact",
  "resources",
  "themes",
  "lara-light-indigo",
  "theme.css"
);
const target = path.join(__dirname, "..", "src", "theme", "bdoi", "primereact-bdoi.css");

// BDO Style Guide colours (see src/theme/bdoi/tokens.scss for the names).
const palette = [
  // Indigo shades -> CTA Blue, its hover and pressed tones, Header Blue and the light blues.
  [/#6366f1/gi, "#0072d8"], // primary
  [/#4f46e5/gi, "#005fb4"], // primary hover
  [/#4338ca/gi, "#004ea8"], // highlight text (Header Blue)
  [/#c7d2fe/gi, "#99c1e7"], // focus ring (Text Field Blue)
  [/#eef2ff/gi, "#e5f5ff"], // highlight background (Background Blue)
  [/rgba\(99,\s*102,\s*241,/gi, "rgba(0, 114, 216,"],
  // Neutrals: never pure black; the guide's greys.
  [/#374151/gi, "#2e2e2e"], // near black
  [/#4b5563/gi, "#4b4b4b"], // dark grey (text)
  [/#6b7280/gi, "#656565"], // base grey (secondary text)
  [/#9ca3af/gi, "#919191"], // medium grey (placeholder, disabled)
  [/#d1d5db/gi, "#c2c2c1"], // light grey
  [/#e5e7eb/gi, "#e4e4e4"], // borders
  [/#f3f4f6/gi, "#f0f0f0"],
  [/#f9fafb/gi, "#f6f6f6"], // dirty white
  [/--surface-border:\s*#dfe7ef/g, "--surface-border: #e4e4e4"],
  [/--surface-hover:\s*#f6f9fc/g, "--surface-hover: #e5f5ff"],
  // Type and radius.
  [/"Inter var",\s*sans-serif/g, '"Nunito", Arial, sans-serif'],
  [/font-family:\s*"Inter var";/g, 'font-family: "Nunito", Arial, sans-serif;'],
  [/--border-radius:\s*6px/g, "--border-radius: 8px"],
];

let css = fs.readFileSync(source, "utf8");
// The stock theme bundles Inter through an @font-face; Nunito comes from @fontsource instead.
css = css.replace(/@font-face\s*\{[^}]*Inter[^}]*\}\s*/g, "");
for (const [pattern, replacement] of palette) {
  css = css.replace(pattern, replacement);
}
const banner =
  "/* Generated by scripts/build-bdoi-theme.js from primereact lara-light-indigo. Do not edit by hand. */\n";
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, banner + css);
console.log(`wrote ${path.relative(process.cwd(), target)} (${css.length} bytes)`);
